package com.hpe.morpheus.harvester.plugin.utils.parsers

import groovy.util.logging.Slf4j

/**
 * Common parser utilities for Kubernetes resource values
 * Purpose: Provides reusable parsing methods for Kubernetes resource formats
 * Author: Generated by GitHub Copilot
 * Date: August 26, 2025
 */
@Slf4j
class CommonParser {

    /**
     * Helper method to parse CPU resource values (e.g., "4", "4000m")
     * @param valueObj The CPU value object from Kubernetes API
     * @return Parsed CPU cores as Long
     */
    static Long parseCpuValue(Object valueObj) {
        if (!valueObj) return 0L
        String value = valueObj.toString()

        try {
            if (value.endsWith('n')) {
                // Nano-cores (e.g., "1000000n" = 1 milli-core = 0.001 cores)
                return Long.parseLong(value.substring(0, value.length() - 1)) / 1000000000
            } else if (value.endsWith('m')) {
                // Milli-cores (e.g., "4000m" = 4 cores)
                return Long.parseLong(value.substring(0, value.length() - 1)) / 1000
            } else {
                return Long.parseLong(value)
            }
        } catch (NumberFormatException ignored) {
            log.warn("Could not parse CPU resource value: ${value}")
            return 0L
        }
    }

    /**
     * Helper method to parse memory/storage values (e.g., "8Gi", "8192Mi", "117818k")
     * This method handles both memory and storage since they use the same Kubernetes units
     * @param valueObj The memory/storage value object from Kubernetes API
     * @return Parsed value in bytes as Long
     */
    static Long parseMemoryValue(Object valueObj) {
        if (!valueObj) return 0L
        String value = valueObj.toString()

        try {
            if (value.endsWith('Ki')) {
                return Long.parseLong(value.substring(0, value.length() - 2)) * 1024
            } else if (value.endsWith('Mi')) {
                return Long.parseLong(value.substring(0, value.length() - 2)) * 1024 * 1024
            } else if (value.endsWith('Gi')) {
                return Long.parseLong(value.substring(0, value.length() - 2)) * 1024 * 1024 * 1024
            } else if (value.endsWith('Ti')) {
                return Long.parseLong(value.substring(0, value.length() - 2)) * 1024L * 1024L * 1024L * 1024L
            } else if (value.toLowerCase().endsWith('k')) {
                return Long.parseLong(value.substring(0, value.length() - 1)) * 1024L
            } else if (value.toLowerCase().endsWith('m')) {
                return Long.parseLong(value.substring(0, value.length() - 1)) * 1024L * 1024L
            } else {
                return Long.parseLong(value)
            }
        } catch (NumberFormatException ignored) {
            log.warn("Could not parse memory/storage value: ${value}")
            return 0L
        }
    }
}
